package com.example.minicommerce.payment;import static org.assertj.core.api.Assertions.*;import com.example.minicommerce.payment.application.WebhookSignature;import com.example.minicommerce.shared.config.AppProperties;import com.example.minicommerce.shared.error.BusinessException;import java.time.Duration;import org.junit.jupiter.api.Test;class WebhookSignatureTest{@Test void invalidSignature_isRejected(){AppProperties p=new AppProperties(new AppProperties.Jwt("x","eHh4eHh4eHh4eHh4eHh4eHh4eHh4eHh4eHh4eHh4eHg=",Duration.ofMinutes(1),Duration.ofDays(1)),new AppProperties.Payment("secret",Duration.ofMillis(1),Duration.ofMillis(1)),new AppProperties.Cache(Duration.ofMinutes(1),Duration.ofSeconds(1),Duration.ofSeconds(1)),new AppProperties.Outbox(1,Duration.ofSeconds(1),Duration.ofSeconds(1),Duration.ofSeconds(1)));WebhookSignature s=new WebhookSignature(p);assertThatThrownBy(()->s.verify("{}","00")).isInstanceOf(BusinessException.class);}}
